#!/usr/bin/env python3
"""Manually judged claim map; source copying and serialization only are automated."""
import json
from pathlib import Path
from author_literature import refs
P=Path(__file__).resolve().parent
items={int(x['id'].split('-')[1]):x for x in json.loads((P/'items.json').read_text())}
refmap={x['key']:x for x in refs}
claims=[]
def c(n,item,statement,status,cls,fate,keys,family,proof='No numerical computation is asserted; see the specified source comparison.',confidence='high',words=None,origin='manuscript',refined=None):
 a=items[item]; rr=['R-'+x for x in keys]
 dates='; '.join(f"{x}: {refmap[x]['first_circulation']}; publication {refmap[x]['publication']}" for x in rr if x in refmap)
 claims.append(dict(id=f'SA05-C{n}',items=[a['id']],cote=a['cote'],scans=a['scans'],lines=a['lines'],
  his_statement=words or a['his_words'],statement=statement,status_on_pages=status,computation=proof,
  **{'class':cls},fate=fate,fate_date=dates or 'No exact historical development date identified.',
  present_status='As of 2026-11-19: '+fate,refs=rr,confidence=confidence,search_ids=[f'ROOT-{family}'],
  origin=origin,refined_statement=refined))

# Initial category, level, and fibre functors.
c(1,1,'A rational semisimple category of pure effective motives with all the listed faithful classical realizations is postulated for the stated fields.','stated without proof','C','Numerical semisimplicity is proved by Jannsen; a faithful realization of numerical motives requires an additional comparison of equivalence relations. The full package remains conjectural in general.',['Jannsen1992','CadoretHuiTamagawa','MilneReport2026'],'PURE')
c(2,2,'The pure effective weight-one category is contravariantly equivalent to abelian varieties up to isogeny, with the Picard/dual convention.','stated without proof','B','The h1/abelian-variety correspondence is established in concrete homological and motivated settings. It does not construct the whole postulated category.',['Tate1966','Faltings1983','DM1982','MilneAV2008'],'FROB')
c(3,3,'Base extension between algebraically closed fields is fully faithful on the chosen pure-motive category.','stated without proof','C','This depends on the equivalence relation and realization. DM6.22 explicitly corrects an overstrong essential-surjectivity claim; full faithfulness and equivalence must not be conflated. The manuscript does not specify enough to identify a universal theorem.',['DM1982','Kahn2025'],'TAN',confidence='medium')
c(4,3,'Level and pure-level decompositions are invariant under algebraically closed base extension.','corrected by himself later: cancelled at12/003, early line59','F','The sentence is cancelled. No surviving assertion with complete level hypotheses is identified; modern descent is not a replacement for the removed statement.',['Kahn2025','Milne1994'],'PURE',confidence='medium')
c(5,4,'The written Künneth and invertible-P1-projector conditions alone give the stated universal category of motives.','stated without proof','C','Correspondence constructions require cycle maps and compatibility with composition. Later universal constructions supply specified categories, not this incomplete presentation.',['Jannsen1992','CG2017'],'PURE')
c(6,5,'In the proposed finite-length semisimple category with a well-defined minimal level, each object uniquely decomposes into pure-level summands.','proof sketched','E','This follows from partitioning its simple constituents by minimal level; existence of the proposed level and category is a separate premise.',['Jannsen1992'],'PURE','Independent finite-length argument in root_checks.md §1; Tate-weight test family in root_certificates.json.')
c(7,6,'The displayed twist (n−i)/2 converts an effective weight-i constituent into weight n under the convention Q(-1) has weight2.','false as stated under that convention','F','The literal formula has the opposite sign. The corrected modern twist is(i−n)/2; the scan must decide whether the ink or a convention differs.',['WeilII1980','Milne1994'],'WEIGHT','root_certificates:Tate weights; root_checks.md §1. Refined formula is SA05-C141.',refined='SA05-C141')
c(8,7,'Weak Lefschetz injects H^i(X) into H^i(Y) for a smooth complete-intersection i-dimensional section Y of smooth projective X.','proof sketched by reference to Lefschetz','E','The cohomological statement is standard under the stated smooth/projective hypotheses. A split motivic injection additionally uses the correspondence formalism and semisimplicity.',['Deligne1968','WeilII1980'],'PURE')
c(9,8,'Classes supported in codimension j have motivic level at most i−2j, after resolving supports and using the stated standard conjectures.','stated without proof, explicitly conditional','C','The coniveau spectral sequence is established. Its equality with a conjectural motivic-level decomposition remains a stronger cycle/support assertion in general.',['BlochOgus1974','CadoretHuiTamagawa','MilneReport2026'],'BIR')
c(10,9,'A rigid abelian tensor category with End(1)=k and an exact faithful k-linear fibre functor is equivalent to finite-dimensional representations of its affine tensor-automorphism group.','stated without proof','B','The precise neutral reconstruction theorem is DM2.11. The existence of the motive category and its fibre functor remain additional hypotheses.',['DM1982'],'TAN')
c(11,9,'A neutral Tannakian group is of finite type precisely when the category has a tensor generator in the stated sense.','stated without proof','B','DM2.20 gives the finite-generation criterion. No finite generator of all motives is thereby obtained.',['DM1982'],'TAN')
c(12,9,'In characteristic zero, semisimplicity corresponds to reductivity/pro-reductivity in the connected affine group setting.','stated without proof','B','DM2.23 is stated for connected affine groups; this hypothesis is retained. The page’s use needs its own connectedness or component argument.',['DM1982'],'TAN')
c(13,9,'End(1)=k is the category’s connected-unit condition.','stated without proof','E','This does not imply connectedness of its Tannakian group: Rep_k of a nontrivial finite group has End(1)=k. DM2.22 gives the separate group-connectedness criterion.',['DM1982'],'TAN','Independent finite-group example; root_checks.md §1.')
c(14,10,'A generic motive category over a regular base and its pullback functors can be defined as indicated.','open on the pages: à expliciter','C','Triangulated motivic theories and descent are established with explicit bases and coefficients; the proposed abelian generic-category formalism is not completely supplied here.',['CD2019','Kahn2025'],'SIX')
c(15,11,'Tensor-isomorphisms between two fibre functors form a torsor under the tensor-automorphism group.','stated without proof','B','DM3.2 proves the formal torsor theorem for Tannakian categories. It is not a genericity statement about a comparison point.',['DM1982','Huber2020'],'TAN')
c(16,11,'The finitely generated category becomes neutral over a finite coefficient extension.','open on the pages: à prouver','C','A finite-type Tannakian gerbe has a closed point after suitable field extension; the needed Tannakian hypotheses cannot be replaced by rigidity alone. Deligne7.1 supplies the characteristic-zero dimension criterion.',['Deligne1990','DM1982'],'TAN','The superline has categorical dimension−1 and rules out an ordinary symmetric fibre functor; root_checks.md §1.')
c(17,12,'Different Betti embeddings produce forms of the same motivic group related through fibre-functor torsors.','open on the pages','B','The torsor/inner-form mechanism is established once both fibre functors exist on the same specified Tannakian category; it does not canonically identify their points.',['DM1982'],'TAN')
c(18,13,'A supersingular elliptic curve obstructs a faithful two-dimensional rational fibre functor respecting its full geometric endomorphism algebra.','proof sketched, attributed to Serre','E','Its quaternion division endomorphism algebra cannot embed in M2(Q). This is an obstruction to this rational realization, not to l-adic fibres or nonneutral Tannakian categories.',['Milne1994','MilneAV2008'],'TAN','Independent dimension-and-division-algebra proof, root_checks.md §1.')
c(19,14,'Associating a fibre functor with a geometric point includes an identification on the Artin subcategory.','stated without proof','B','The Artin fibre identification is genuine extra data in arithmetic Tannakian descent; an abstract fibre functor alone does not choose it.',['DM1982','Kahn2025'],'TAN')
c(20,15,'Restriction to Artin motives yields a faithfully flat morphism from the arithmetic motivic group to the absolute Galois group scheme.','proof sketched','B','DM2.21 and6.23, and Kahn5.10 in its descent setting, identify the precise arithmetic quotient.',['DM1982','Kahn2025'],'TAN')
c(21,15,'The kernel of the arithmetic quotient equals the identity component without further hypotheses.','corrected by himself later: unconditional assertion cancelled12/008; surviving conditional statement12/009','C','Exactness identifies the geometric kernel. Its connectedness is separate; DM6.22–6.23 retain the relevant Hodge/absolute-cycle condition.',['DM1982','Kahn2025'],'TAN')
c(22,15,'Finite covers and Artin objects recover the profinite quotient in the proposed motivic fundamental-group picture.','proof sketched','B','Finite étale descent and the Artin tensor subcategory supply this quotient in specified motivic theories. This does not identify the entire motivic group with a profinite group.',['DM1982','Kahn2025'],'TAN')
c(23,16,'The l-adic realization supplies a section on Q_l-valued points of the arithmetic motivic group.','stated without proof','B','The compatible pointwise representation is part of the established arithmetic realization picture. A pointwise continuous section is not a section of Q-group schemes.',['DM1982','Kahn2025'],'TAN')
c(24,17,'Tate fullness together with semisimplicity makes the l-adic Galois image Zariski dense in the proposed motivic group.','stated without proof, explicitly conditional','C','The invariant-tensor argument is valid in the specified neutral category. General Tate/semisimplicity hypotheses remain substantive; new2026 abelian results have their restricted scope.',['DM1982','CadoretHuiTamagawa','MilneReport2026'],'FROB')
c(25,18,'Finite-field Frobenius is a central tensor automorphism of the motive category.','proof sketched','B','Functorial Frobenius and tensor compatibility give a central element in the finite-field motivic setting; Milne’s finite-field formalism makes this precise.',['Milne1994'],'FROB')
c(26,18,'Under Tate and semisimplicity, the finite-field motivic group has the indicated commutative/protorus description and Artin component quotient.','stated without proof, explicitly conditional','C','Milne1994 gives the conditional classification by Weil numbers. This is not an unconditional description of all motives over every finite field.',['Milne1994','MilneReport2026'],'FROB')
c(27,19,'Rationality of conjugacy invariants describes a Frobenius point in the adjoint quotient T/W for a connected reductive group.','stated without proof','E','The adjoint-quotient formulation is standard in the connected reductive setting; rational invariant values do not necessarily select a rational representative of every stable conjugacy class.',['DM1982','Milne1994'],'TAN',confidence='medium')
c(28,20,'The weight grading gives a central cocharacter of the motivic group.','stated without proof','B','A tensor-compatible functorial grading corresponds to a central weight cocharacter in the appropriate Tannakian setting. It cannot be a nontrivial Lefschetz sl2 Cartan.',['DM1982','Ziegler2015'],'TAN','root_certificates:SL2 commutator [H,L]=2L; root_checks.md §1.')
c(29,21,'The Hodge cocharacters have product equal to the weight cocharacter and the Tate character satisfies ε(γ(t))=t².','stated without proof','B','The standard Hodge/Tate conventions support this identity with Q(-1) of weight2; complex-conjugation notation and the sign convention are retained.',['DM1982'],'POS','root_certificates:Tate weights and parity; no alternate convention silently substituted.')
c(30,22,'Splittings of a filtered fibre functor form a torsor under the unipotent kernel of the filtered-to-graded automorphism group.','stated without proof','B','Ziegler4.13 proves fpqc-local splittability and4.14 identifies the splitting torsor; these are the exact local-existence and torsor steps.',['Ziegler2015'],'TAN')
c(31,23,'Polarizable rational pure Hodge structures form the proposed rigid semisimple tensor setting.','stated without proof','B','The Hodge realization category supplies this established model with the graded commutativity convention handled explicitly. It does not prove algebraicity of every Hodge tensor.',['DM1982','Deligne1990'],'POS')
c(32,23,'A real invariant bilinear form is automatically positive.','open on the pages under uncertain wording','F','Invariance alone is insufficient: diag(1,−1) is nondegenerate and invariant under the trivial group but indefinite. A polarization or positivity hypothesis is needed; the exact intended assertion is uncertain.',['DM1982'],'POS','root_certificates:indefinite form; root_checks.md §1.',confidence='medium')
c(33,24,'The Mumford–Tate group is determined by rational Hodge tensors.','stated without proof','B','Tensor stabilizers give the usual Mumford–Tate construction. Its comparison with the algebraic-cycle motivic group is a separate fullness conjecture.',['DM1982','MilneReport2026'],'POS')
c(34,24,'Hodge fullness identifies the group denoted G0 on the page with the Hodge/Mumford–Tate group.','stated without proof, conditional','C','The equality is conditional on the appropriate cycle fullness. The page’s subscript0 is not automatically an identity-component symbol. General complex varieties and arbitrary complex abelian varieties are not covered by the2026 CM theorem.',['DM1982','MilneReport2026'],'POS')

# General bases and three distinct filtrations.
c(35,26,'An abelian category M(X) with the stated tensor and derived six-operation properties exists on general bases.','stated without proof','C','Rational triangulated motives provide a large part of the formalism; a compatible abelian motivic heart with every listed property is not supplied in this generality.',['CD2019'],'SIX')
c(36,26,'Rf_* preserves the relevant constructible category for finite-type f when f is proper or the target is excellent, in the intended setting.','stated without proof','C','The exact constructibility theorem depends on the realization/motivic category. The manuscript’s conjunction finite type AND(proper OR excellent target) is retained; it cannot be shortened to properness alone.',['CD2019','WeilII1980'],'SIX',confidence='medium')
c(37,27,'The category and its functors commute with the indicated affine inverse limits of bases, with finite-stage descent of finite data.','stated without proof','C','Cisinski–Déglise establish continuity for specified triangulated categories; their introductory Theorem 7, citing 15.2.4 and 15.1.6, gives the complete constructible formalism for separated finite-type schemes over an excellent base of dimension less than 2. This checked scope does not prove continuity of the manuscript’s unspecified abelian heart or remove the base hypotheses.',['CD2019'],'SIX')
c(38,28,'Exact faithful realization detects kernels,cokernels and isomorphisms after a morphism has been constructed.','proof sketched','E','This is elementary abelian-category reasoning. Faithfulness is not fullness and cannot manufacture a motivic morphism lifting an l-adic one.',['DM1982'],'TAN','Independent kernel/cokernel argument in root_checks.md §1.')
c(39,28,'The tensor unit has the asserted nonzero realization and the zero category is excluded.','stated without proof','E','The unit constraint in a faithful unital tensor functor enforces this. It is a consistency condition, not a construction theorem.',['DM1982'],'TAN','Independent tensor-unit check, root_checks.md §1.')
c(40,29,'A coherent realization of the proposed motives has the listed compatibility properties.','corrected by himself later: entire paragraph cancelled12/026','F','No surviving coherent-realization theorem with these properties is asserted on the page. Later de Rham/coherent realizations require a separately specified theory.',['CD2019'],'SIX',confidence='medium')
c(41,30,'P1 decomposes into the unit and Tate object, and top compactly supported cohomology of a smooth geometrically connected nonempty n-fold gives Q(-n).','stated without proof','B','Projective-bundle and trace/purity formalisms establish these statements in the standard realization and motivic settings with the stated hypotheses.',['CD2019','WeilII1980'],'SIX','root_certificates:Tate weights; root_checks.md §2.')
c(42,31,'For a regular immersion of codimension d, i!Q is written as Q(-d) without a cohomological shift.','false as stated in the derived category','F','Absolute purity requires Q(-d)[-2d]. CD14.4.1 gives the rational motivic formula under regularity; the scan may restore an omitted shift.',['CD2019'],'SIX','root_certificates:purity shifts; refined SA05-C142.',refined='SA05-C142')
c(43,32,'Full faithfulness of the Tate-shift functor permits localization by formally inverting the Tate object.','stated without proof','B','Stabilization/localization is an established construction with the relevant full-faithfulness/cancellation input. The opposing twist signs in the manuscript must be reconciled on the scan.',['CD2019'],'SIX')
c(44,33,'Internal Hom,duality and exceptional pullback satisfy the displayed formal relations.','stated without proof','C','Closed tensor and six-operation theories realize such relations with constructibility and dualizability hypotheses. Merely naming internal Hom does not construct f!.',['CD2019'],'SIX')
c(45,34,'For an already existing common motive, lissity and rank are independent of the chosen l-adic realization.','stated without proof','C','Compatibility theorems exist in specified settings, but the universal common motivic category and all its realization-independence assertions are not constructed by this page.',['CD2019','CadoretHuiTamagawa'],'SIX')
c(46,35,'Categorical traces and characteristic coefficients lie in End(1)=Q and are independent of realization.','proof sketched','E','Trace/evaluation and exterior-power identities prove this within a rigid Q-linear tensor category and compatible symmetric realizations. The contraction in the written formula must be the correctly typed one.',['DM1982','Deligne1990'],'TAN','Independent categorical argument and trace calculations in root_checks.md §1; root_certificates:trace series.')
c(47,36,'Weights over a finite-type Z-model can be tested at all closed points and are compatible with the stated functors.','stated without proof','B','Deligne’s weight theory supplies the arithmetic realization formulation under its mixedness hypotheses. It does not canonically produce the conjectural motivic filtration.',['WeilII1980'],'WEIGHT')
c(48,36,'R^j f_! sends weights≤w to weights≤w+j.','stated without proof','B','WeilII3.3.1–3.3.4 establishes the upper-weight theorem for the corresponding constructible l-adic setting.',['WeilII1980'],'WEIGHT')
c(49,37,'Tate twists alter weight by an even integer; an odd-weight object cannot become weight zero by an integral Tate twist.','proof sketched','E','This follows from wt(Q(1))=−2. A display identifying all Gi with G0 must contain a parity qualification or an index2i.',['Milne1994','DM1982'],'WEIGHT','root_certificates:Tate parity, root_checks.md §2.')
c(50,38,'The early dimension filtration D is stable under every Tate twist and assigns dimension-type zero to every Tate object.','stated without proof','C','This is the manuscript’s definition/proposed structure. It differs from ordinary geometric dimension and from the later generation filtration; no contradiction is inferred merely from the reused letterD.',['Milne1994','BlochOgus1974'],'WEIGHT','root_certificates:unit,Tate andh1 test objects; root_checks.md §2.')
c(51,38,'The uncertain ordinary R^j f_* and Ext inequalities obey the displayed D-indices.','open on the pages, with question marks and competing indices','F','The intended exact bound is not recoverable without choosing between the written candidates and specifying the category. Standard weight bounds do not settle the stronger dimension-type assertion.',['WeilII1980','CD2019'],'WEIGHT',confidence='low')
c(52,39,'Lisse motives are extension-stable and the written Ext-vanishing statement holds.','stated without proof with ambiguous global/internal Ext','C','Extension stability is natural in lisse realization categories. Global Ext need not vanish, whereas internal exactness/semisimplicity over a point is a different statement; the draft lacks the distinction required for a uniform theorem.',['DM1982','CD2019'],'SIX',confidence='medium')
c(53,40,'K0 of the proposed finite-length semisimple category is freely generated by its simple objects.','proof sketched','E','Jordan–Hölder gives the free abelian basis. This is K0 of a category of motives, not K0 of varieties.',['Weibel2013','Jannsen1992'],'ENDO','Independent simple-multiplicity proof, root_checks.md §2.')
c(54,40,'The Tate class is not a zero divisor in that motivic Grothendieck ring.','stated without proof','E','An invertible Tate object acts as a permutation of simple classes and therefore injectively; in an effective category this needs the fully faithful Tate-shift input. This says nothing about the affine-line class in K0(Var).',['Weibel2013','LarsenLunts2003'],'ENDO','Independent permutation-of-basis argument, root_checks.md §2.')
c(55,41,'The weight grading and the Tate polynomial/Laurent-polynomial presentation have the displayed degrees.','stated without proof with inconsistent degree conventions','F','The Tate object has weight2; assigning it degree1 is a regrading of even weights. Inverting it requires Laurent powers. No single literal grading satisfies all displayed formulas without a convention repair.',['Milne1994','Weibel2013'],'WEIGHT','root_certificates:degree and Tate parity tests.')
c(56,42,'The primitive class α0 is obtained by the displayed subtraction from itself.','false as stated if α0 is meant to retain the unit','F','The literal formula gives zero and loses the unit. The range of primitive subtraction needs a boundary exception or a different index.',['Weibel2013'],'ENDO','root_certificates:primitive-zero boundary; refined SA05-C143.',refined='SA05-C143')
c(57,42,'Primitive Tate strings supply a basis/decomposition of the motivic ring, and the written D-quotient has the asserted presentation.','stated without proof','C','A decomposition by simple Tate orbits is elementary when its hypotheses hold; ring multiplication requires additional structure constants. The proposed D-quotient is not established by a basis calculation.',['Milne1994','Weibel2013'],'ENDO','Explicit small Tate strings and product-data separation in root_checks.md §2.')
c(58,43,'Primitive level0 and1 pieces are completely described as promised.','open on the pages: description deferred','C','Artin and h1/abelian categories supply important low-level models; the full identification depends on the exact motive category and level convention. The promised proof is not on these pages.',['DM1982','Tate1966','Milne1994'],'PURE')
c(59,43,'Duality produces the asserted involution and λ-operations descend to the proposed primitive quotient.','open on the pages','C','Duality and λ-operations exist in rigid tensor K0; descent to this particular quotient needs stability of its defining relations. No exact general result for the draft quotient was found.',['Weibel2013','KahnSujatha2016'],'ENDO',confidence='medium')
c(60,45,'The coniveau complex has E1-terms formed from residue-field cohomology in the specified Ind-motivic setting.','proof sketched with unresolved indices','B','The realized coniveau spectral sequence and its E1/E2 distinction are established by Bloch–Ogus; the manuscript’s Ind-motivic lift and exact level equality are additional claims.',['BlochOgus1974'],'BIR')
c(61,46,'For a dense open immersion the selected pure-dimensional part has kernel/cokernel in the displayed lower D-levels.','corrected by himself later: cancelled12/043 and12/058; later surviving formulation12/047','C','Weight/coniveau localization gives related bounds, but the precise Tate-stable D formulation and missing smoothness hypotheses are not settled by those results alone.',['BlochOgus1974','WeilII1980','KahnSujatha2016'],'BIR',confidence='medium')
c(62,47,'Compactly supported Euler characteristic gives an additive multiplicative map from varieties to a suitable motivic K0.','proof sketched','B','Gillet–Soulé Theorem4 gives the characteristic-zero Chow-motive Euler characteristic with scissors and product properties. General-base variants require a specified theory.',['GilletSoule1996','CD2019'],'BIR','Additivity and signs checked on A1,P1 and a curve in root_checks.md §2.')
c(63,48,'The first birational-motivic map is an isomorphism or injective modulo torsion as tentatively asked.','corrected by himself later: question cancelled12/044 and12/052','C','Later birational-motive constructions establish well-defined quotients/localizations, not faithfulness on birational classes of varieties. The withdrawn assertion is not restored.',['KahnSujatha2016','LarsenLunts2003'],'BIR')
c(64,48,'The later D′ filtration uses geometric generating dimension and γ-pieces in weightsn,n+1.','stated without proof','C','This is a different filtration from the earlier Tate-stableD. Related weight and birational constructions exist, but the exact proposed isomorphism is not identified with a proved theorem.',['WeilII1980','KahnSujatha2016'],'BIR','root_certificates:curve/surface weights andEuler signs.')
c(65,49,'Every nondominant rational map induces zero on the proposed birational γ functor.','false as stated','F','A section C→C×P1 is nondominant and has the projection as retraction; functoriality and nonzeroγ1(C) contradict the assertion. A restricted degree/component statement must replace it.',['KahnSujatha2016','Tate1966'],'BIR','Retraction proof with every dimension hypothesis in root_checks.md §3; refined SA05-C144.',refined='SA05-C144')
c(66,49,'The relevant Ind-motive has a largest bipure subobject of the required finite type.','open on the pages','C','An Ind-category contains filtered unions of subobjects, but finite length/compactness of the resulting maximal subobject requires a bound not supplied here. No exact unconditional theorem matching all draft requirements was found.',['CD2019','KahnSujatha2016'],'BIR',confidence='medium')
c(67,50,'The birational motive functor lifts the stated motive morphisms to geometric/field morphisms after purely transcendental stabilization.','open on the pages','C','The word faithfulness does not express the actual fullness/lifting question. Howe’s curve example obstructs unrestricted lifting. The manuscript calls the extension purely transcendental and also uses bracket notation for a field, so the polynomial-ring units calculation is only a conditional notation alarm, not a refutation of its intended stabilization.',['KahnSujatha2016','Howe2005'],'BIR','Curve factorization and Riemann–Hurwitz in root_checks.md §3; the separate field-to-polynomial-ring argument applies only if brackets are literal polynomial notation.')
c(68,51,'An unpolarized Jacobian or its isogeny class determines a curve up to the proposed stabilized rational maps.','false as stated in the unrestricted lifting interpretation','B','Howe’s explicit nonisomorphic genus-two curves have isomorphic unpolarized Jacobians. Maps from rational factors to a positive-genus target are constant, and Riemann–Hurwitz forces a degree-one map between genus-two curves to be an isomorphism.',['Howe2005','MilneAV2008'],'BIR','t=2 parameter hypotheses and RH calculation, root_checks.md §3; root_certificates:curve degrees. Refined SA05-C145.',refined='SA05-C145')
c(69,52,'Vanishing of every positive primitive motivic invariant implies unirationality.','open on the pages; false for the rational homological interpretation','B','A complex Enriques surface has a rational homological motive consisting of Tate pieces but is not unirational. This conclusion is not asserted for its integral or full Chow motive.',['Dolgachev2016','GilletSoule1996'],'BIR','Betti/Hodge/divisor andpluricanonical checks in root_checks.md §3; refined SA05-C146.',refined='SA05-C146')
c(70,53,'The author considers a graded scissors-ring comparison and rejects its suggested geometric consequence that algebraic H2 forces a surface to be ruled.','corrected by himself later: the geometric consequence is rejected using supersingular E×E at12/050','C','The product is not ruled although its H2 is algebraic. This refutes the geometric implication; nonruledness alone does not prove its class is nonzero in the proposed graded scissors quotient, so it is not a complete counterexample to injectivity of that ring map. Larsen–Lunts proves a different characteristic-zero quotient theorem.',['LarsenLunts2003','GorenLauter2006','MilneAV2008'],'BIR','For supersingular E², NS rank6=b2 and H1 rank4; absence of rational curves excludes ruledness. The exact ring-isomorphism question remains separate; root_checks.md §3.')
c(71,56,'The earlier notes identify a linear Nori/Ayoub comparison and a separate nonlinear motivic Galois comparison.','not an assertion of the manuscript; earlier-run comparison','B','CG9.1 gives the Hopf comparison for k⊂C and PID coefficients. Ayoub2026 identifies an enriched geometric-functor automorphism group; it does not identify a bare profiniteπ1 or prove all derived triviality.',['CG2017','Ayoub2026'],'MODERN',origin='earlier-run comparison checked in current literature')
c(72,57,'Existence of a period torsor entails genericity of its comparison point.','not on the pages; explicitly rejected inference','C','The formal torsor theorem and the period conjecture are separate. Huber5.14–5.15 formulates the extra connectedness/genericity/transcendence assertion.',['DM1982','Huber2020'],'MODERN',origin='boundary check on earlier-run comparison')
c(73,58,'The algebraic part/centre of the proposed fundamental Lie motive is scalar or zero as the final paragraph suggests.','open on the pages; Pro/Codex surviving-word disagreement','F','Pro retains scalar wording; Codex retains nul and deletes the scalar alternative. The exact intended statement cannot be chosen here, and different categorical/group-theoretic centres are not interchangeable.',['DM1982','Milne1994'],'TAN',confidence='low')

# Middle arithmetic and positivity calculations.
c(74,61,'For a smooth n-fold, every Hc^i(X) belongs to the weight≤n category.','false as stated','F','Hc²(P1)=Q(-1) has weight2 with n=1. Both witnesses retain the bound; a dimension-filtration or degree-dependent repair needs the scan.',['WeilII1980'],'WEIGHT','root_certificates:P1 andTate weights; refined SA05-C147.',refined='SA05-C147')
c(75,62,'For smooth X of dimension n and a lisse geometric coefficient F of pure weight rho, the proposed upper bound wt H^i(Xbar,F)<=rho+min(2i,2n) extends the sharp constant-coefficient bound; the source also has an unresolved n/2n variant.','false as stated under unrestricted lisse interpretation','B','The Legendre sheaf F=R1g_*Q_l of weight1 over A1−{0,1}/F5 has H1 of weight4, exceeding1+min(2,2)=3. It also satisfies the stronger smooth-projective direct-summand hypothesis used later at scan108. Deligne’s lisse lower-weight theorem does not give the proposed upper bound.',['LegendreStacks','WeilII1980'],'WEIGHT','Exact all-extension trace formula and duality in root_checks.md §4; finite samples root_certificates:Legendre. Refined SA05-C148.',refined='SA05-C148')
c(76,62,'The displayed absolute H1 coefficient window excludes all pure weights below−2.','false as stated for arbitrary lisse coefficients','B','For the same LegendreV, V(2) has weight−3 and geometric H1 has Frobenius eigenvalue1, giving nonzero arithmetic H1. This checks the exact forbidden range.',['LegendreStacks','WeilII1980'],'WEIGHT','Hochschild–Serre edge term with no geometric invariants, root_checks.md §4; refined SA05-C148.',refined='SA05-C148')
c(77,62,'The printed i=1 interval[-2,1] follows from the preceding sharper inequalities.','proved there as a weaker consequence','E','The inequalities give[-2,0], which is contained in[-2,1]. The loose upper endpoint is an ink alarm if sharpness was intended, not a false logical consequence.',['WeilII1980'],'WEIGHT','root_certificates:weight intervals; direct inequality check.')
c(78,63,'Tate plus the stipulated semisimplicity identifies K0 of motives with its realization image.','proof sketched, explicitly conditional','C','Fullness distinguishes simple constituents in the required way. A faithful exact functor without fullness can identify distinct simples after realization; the broad Tate input remains.',['DM1982','Milne1994','CadoretHuiTamagawa'],'FROB')
c(79,64,'Frobenius integrality characterizes effectivity.','open on the pages, Tate condition in margin','C','For finite-field pure motives under Tate, Milne2.6 constructs effective motives from integral Weil numbers; the direct integrality statement is2.3. The unrestricted general-base converse is not this theorem.',['Milne1994','WeilII1980'],'FROB')
c(80,65,'The weight-zero integral Frobenius eigenvalues are roots of unity.','proof sketched','E','Kronecker’s argument applies to algebraic integers all of whose conjugates have modulus1. Uniform rationality/degree bounds are needed to pass from this pointwise fact to bounded orders.',['Milne1994'],'FROB','Independent coefficient-bounded-powers argument in root_checks.md §4.')
c(81,65,'Root-of-unity eigenvalues alone imply finite monodromy.','false without the separate semisimplicity input','E','An infinite unipotent l-adic representation has every eigenvalue1. Under semisimple arithmetic geometric hypotheses and uniform bounded orders, the finite-image inference has the required additional support.',['DM1982','Milne1994'],'FROB','root_certificates:unipotentJordan; root_checks.md §4; refined SA05-C149.',refined='SA05-C149')
c(82,66,'The dimension filtration can be described by a naive filtration ofπ1.','open on the pages, author explicitly doubts the generalization','D','Searches of finite-field motivic groups, contemporary Tate formulations and birational motives found no exact theorem supplying this rejected naive construction. A new precise Tannakian formulation is needed.',['Milne1994','CadoretHuiTamagawa','KahnSujatha2016'],'FROB',confidence='medium')
c(83,67,'In the stated semisimple representation setting, taking the commutant twice recovers the associative image algebra.','proof sketched','E','The finite-dimensional double-centralizer theorem supplies exactly the algebra conclusion; Tate is separately needed to recognize the first commutant geometrically.',['Milne1994'],'FROB','root_certificates:SL2/GL2commutants; root_checks.md §4 generalisotypic argument.')
c(84,67,'The procedure determines individual algebraic cycles rather than only their Q_l-span.','not asserted; the manuscript expressly limits the conclusion','F','The page itself excludes this stronger inference. No algebraic-cycle representative is selected by a vector-space centralizer computation.',['Milne1994'],'FROB',origin='boundary check of manuscript conclusion')
c(85,68,'Invariant vectors after some finite extension are exactly analytic-Lie-invariant vectors.','stated without proof','E','For a compact l-adic analytic image, Lie invariance is equivalent to being fixed by an open subgroup. This is distinct from Zariski-Lie invariance.',['Milne1994','DM1982'],'FROB','Independent exponential-neighbourhood/open-stabilizer proof in root_checks.md §4.')
c(86,69,'Equality of associative envelopes identifies the original groups.','not asserted; the manuscript expressly says only envelope','E','SL2 and GL2 have identical associative envelope M2 in the standard representation and are different groups.',['DM1982'],'FROB','root_certificates:SL2/GL2 basis andcommutants; root_checks.md §4.',origin='earlier-run elucidation')
c(87,70,'The analytic Galois-image Lie algebras are realizations of a single l-independent Lie motive.','open on the pages','C','A motivic/algebraic monodromy Lie object is meaningful in a specified tensor theory, but it cannot automatically represent analytic image Lie algebras. The finite-field example separates dimensions1 and2.',['Milne1994','CadoretHuiTamagawa','Kahn2025'],'FROB','root_certificates:FrobeniusT²−T+5; root_checks.md §4 multiplicative independence.',confidence='medium')
c(88,71,'The proposed absolute-cohomology axioms determine an existing general theory with finite-dimensional rational groups.','open on the pages','C','Weil-étale and triangulated motivic theories realize parts of the desiderata under distinct hypotheses. Geisser7.1 gives a precise rational splitting over smooth finite-field schemes; it is not the whole axiom package.',['Geisser2004','CD2019'],'ABS')
c(89,73,'Absolute Ext1 coincides with Yoneda extensions and higher absolute Ext is effaceable.','open on the pages: hope followed by doubt','C','YonedaExt1 is formal in an abelian category; effaceability of an externally proposed cohomology theory is a new requirement. A general motivic heart realizing the entire proposal is not supplied.',['CD2019','Geisser2004'],'ABS')
c(90,74,'Absolute higher cohomology over an algebraic closure vanishes while H1(Fq,Q)=Q and restrictions multiply by degree.','false as a simultaneous system with the stated continuity','F','The direct limit of Q under nonzero integer multiplications is Q, not zero. One must change the cohomology theory, continuity statement or restriction convention.',['Geisser2004'],'ABS','root_certificates:oddunitrestriction; root_checks.md §5. Refined SA05-C150.',refined='SA05-C150')
c(91,74,'The cycle comparison is with rational correspondences in degree2i and the corresponding odd arithmetic degree2i+1.','stated without proof with index variants','C','Tate-cycle identifications and semisimplicity yield the indicated finite-field realization pattern. The Ri/R2i and j+1/2j+1 variants remain scan questions.',['Tate1966','Milne1994','Geisser2004'],'ABS')
c(92,75,'Arithmetic duality has the displayed Tate twist and shift2n+1, and finite-field pairings use degree sum1.','open on the pages: cup products à développer','C','Arithmetic duality and Weil-étale top-degree formulas provide exact related theorems with support and finiteness conditions. The unfinished cup-product construction and general abelian motive category are not supplied by the analogy.',['MilneADT2006','Geisser2004'],'ABS','root_certificates:duality shifts; root_checks.md §5.')
c(93,76,'Tate identifies the even invariant term, and Tate plus semisimplicity identifies the corresponding odd coinvariant term.','proof sketched','B','The two-term Frobenius complex proves the invariant/coinvariant structure. Their natural identification at eigenvalue1 needs semisimplicity, as the page says.',['Milne1994','Geisser2004'],'ABS','root_certificates:semisimple andunipotentHS matrices; root_checks.md §5.')
c(94,76,'The odd-degree identification is canonical without a chosen arithmetic generator.','not asserted unconditionally; normalization is implicit','F','A generator of the Weil direction normalizes the odd class; restrictions scale by extension degree. The underlying one-dimensional space is not a specified numerical identification withQ.',['Geisser2004'],'ABS','Oddrestriction calculation in root_certificates; root_checks.md §5.')
c(95,77,'The reused algebra fragment asserts a local freeness statement, but its literal B_h/A_h expression and scan label are inconsistent.','stated without proof in incomplete fragment','C','Duplicate to be consolidated into SA05-C1061. The opened primary comparison is EGA IV3,11.9.7–11.9.10; see that canonical claim and its exact reference. All three witnesses support the same reused paragraph, but B′_h over B_h is a proposed reading, not a silently repaired theorem. Preceding hypotheses are missing.',[],'REUSED',confidence='low')
c(96,78,'For the abelian scheme spread, T_mot(A)=R1f_*Q of the dual scheme twisted(1), pure of weight+1.','false as stated for the written Tate convention','F','The expression has weight−1, consistent with the later1−1=0 calculation. The plus sign is a reading alarm; the motivic realization expression retains the dual.',['WeilII1980','Tate1966'],'ARITH','root_certificates:Tate weight; refined SA05-C151.',refined='SA05-C151')
c(97,78,'K-rational points extend to sections of the chosen abelian scheme over the regular integral model S.','stated without proof','E','The classical extension theorem for rational maps from regular schemes to abelian schemes gives A(K)=A(S). Robert, Proposition 2.3.16, states the relative theorem, and SGA 7 IX, proof of 2.2.9, invokes it explicitly. Properness alone on an arbitrary higher-dimensional singular base would not be enough.',['Robert2023','SGA7IX','MilneADT2006'],'ARITH')
c(98,79,'Kummer identifies A(S)⊗Q_l with H1(S,V_l A) once V_lH1(S,A) vanishes.','proof sketched','E','The exact Kummer sequence supplies the criterion. Finiteness of the primary torsor group implies vanishing; the converse requires finite cotype.',['MilneADT2006','KatoTrihan2003'],'ARITH','Kummer exact-sequence derivation in root_checks.md §5.')
c(99,79,'The relevant l-primary Sha-type group is finite for all the stated finitely generated arithmetic situations.','open on the pages','C','This remains a substantive arithmetic conjecture in general. Kato–Trihan proves the exact global-function-field equivalence with the BSD rank equality and the full BSD consequence; it does not prove universal finiteness.',['KatoTrihan2003','MilneADT2006'],'ARITH')
c(100,79,'The rank comparison is essentially equivalent to BSD.','open on the pages, explicitly qualified','C','Kato–Trihan gives a precise equivalence over one-variable global function fields. For a general finitely generated base, and for the full leading coefficient formula, the draft wording needs additional conditions and definitions.',['KatoTrihan2003'],'ARITH')
c(101,80,'For a discrete latticeM, H1(π,M)=(M⊗Q/Z)^π without a quotient.','false as stated','E','The long exact sequence divides by the image of(M⊗Q)^π. For trivialZ, the left side is zero and the written right side isQ/Z.',['MilneADT2006'],'ARITH','root_certificates:discrete lattice; root_checks.md §5; refined SA05-C152.',refined='SA05-C152')
c(102,80,'The map described as bijective on scan77 is surjective with finite kernel on scan79.','corrected by himself later:12/077→12/079','B','The finite-error comparison is sufficient for the intended finiteness question. Local and global duality distinguish it from an integral isomorphism.',['MilneADT2006','MilneWC1972'],'ARITH')
c(103,80,'A(S) is exactly the invariant rational section lattice, without finite torsion correction.','false as stated if interpreted integrally','E','For S=SpecFq, A(Fq) can be nonzero finite while its rational lattice is zero. The correct interpretation is after rationalization or modulo finite groups.',['Tate1966','MilneAV2008'],'ARITH','Explicit finite-section argument in root_checks.md §5; refined SA05-C153.',refined='SA05-C153')
c(104,81,'For a proper smooth positive-genus curve C/Fq with Jacobian J and V_lJ=T_lJ⊗Q_l, the degree-two rational contribution is End_{Fq}(J)⊗Q_l and is nonzero.','proof sketched','B','Tate’s finite-field Hom theorem and Hochschild–Serre verify the endomorphism term. The identity is nonzero, and the tensor expression needs the dual or polarization twist. This is not an identification of the entire integral torsor group with a vector space.',['Tate1966','MilneADT2006'],'ARITH','General constant-Jacobian computation in root_checks.md §5; independently reviewed in the late-scope crossreview.')
c(105,81,'For a proper smooth finite-field curve and an abelian scheme, all the later displayed degree>=2 terms vanish.','false as stated, both in rational comparison and for the literal H2 torsor group','F','The scan78 constant-Jacobian calculation contradicts the scan82 blanket statement. Moreover, Milne ADT II.5.1 and (5.2.1) identify the nonzero rational contribution with V_l H2(C,J×C), since the completed H1 torsor term is finite. Thus literal H2(C,J×C)=0 also fails, without assuming Sha finiteness.',['Tate1966','MilneADT2006'],'ARITH','Counterexample with a positive-genus curve and its constant Jacobian in root_checks.md §5; independent exact example and proof in cote12c/root_crossreview.md. Refined SA05-C154.',refined='SA05-C154')
c(106,82,'Sha-type finiteness is approximately equivalent through Jacobians to Brauer surjectivity modulo finite groups for the proposed fibration.','open on the pages: double question mark','C','Published Brauer–Sha comparisons have base, Picard, period-index and correction-factor hypotheses. The manuscript does not state enough for the unrestricted equivalence; Milne’s correction notice prevents treating its older formula as unconditional.',['MilneBrauer1982','KatoTrihan2003','MilneADT2006'],'ARITH',confidence='medium')
c(107,83,'H^i(S,A)(l) is finite for every i≥3 in the intended general-base setting.','open on the pages','C','Arithmetic duality proves restricted dimension-one results with precise hypotheses; the unqualified higher-dimensional/general-base expectation is not identified with those theorems. Finite cotype is essential when inferring finiteness from a zero Tate module.',['MilneADT2006','CD2019'],'ARITH',confidence='medium')
c(108,84,'For a finite-residue local field of residue characteristicp, H1(K,A) is essentially p-primary modulo finite groups.','stated without proof, already qualified','B','Milne’s1972 addendum extends the local-duality theorem to every abelian variety; the prime-to-p finite-error conclusion matches the qualified page.',['MilneWC1970','MilneWC1972'],'ARITH')
c(109,85,'The written Q_l(1) cohomology separates unit,Picard andBrauer terms by Kummer.','proof sketched','E','Kummer and its inverse limits give the standard exact sequences for l invertible, with the specified completion and Tate-module terms. They do not apply unchanged at the residue characteristic.',['MilneADT2006'],'ARITH','Exact-sequence derivation and term separation, root_checks.md §5.')
c(110,86,'Removing r closed points from a proper finite-field curve increases the Brauer corank by r.','false as stated','E','The global residue relation leaves corankr−1 for r≥1. In particular one puncture gives zero, not one.',['MilneADT2006'],'ARITH','root_certificates:residue matrix rank; root_checks.md §5; refined SA05-C155.',refined='SA05-C155')
